// Configuration: Set to your actual telemetry endpoint when available.
const LIVE_API_URL = ''; // e.g. 'https://api.geotech-monitoring.internal/v1/sensors/telemetry'

if (LIVE_API_URL && LIVE_API_URL.startsWith('http')) {
  // If an API endpoint is configured, fetch dynamically
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: LIVE_API_URL,
    json: true
  });
  return Array.isArray(response) ? response.map(r => ({ json: r })) : [{ json: response }];
}

// Built-in Geotechnical Test Dataset (INSA Lyon GCU / Grenoble INP Ense3 reference)
return [
  {
    json: {
      sensor_id: "INCL-SEC04-A",
      sensor_type: "inclinometer_tilt",
      location: { section: "Pier P3 - North Face", easting: 894520.12, northing: 6451200.45, elevation_m: 214.5 },
      readings: [0.12, 0.14, 0.15, 0.18, 0.22, 0.95] // Breaches warning/critical limit (>0.5 deg)
    }
  },
  {
    json: {
      sensor_id: "STRAIN-SPAN02-MID",
      sensor_type: "strain_gauge",
      location: { section: "Mid-span Girder Box B", easting: 894580.40, northing: 6451250.80, elevation_m: 228.1 },
      readings: [420.0, 422.5, 425.0, 423.8, 424.1, 610.5] // Breaches warning limit (>150 µε)
    }
  },
  {
    json: {
      sensor_id: "PIEZO-ABUT-S",
      sensor_type: "pore_pressure",
      location: { section: "South Abutment Foundation", easting: 894410.00, northing: 6451100.10, elevation_m: 198.3 },
      readings: [85.0, 86.2, 85.8, 86.0, 86.5, 87.1] // Nominal reading (+1.05% change, threshold 15%)
    }
  }
];

const items = $input.all();
const evaluatedItems = [];

// Geotechnical & Structural action thresholds (Eurocode 7 SLS/ULS standards)
const THRESHOLDS = {
  inclinometer_tilt: { warning: 0.5, critical: 1.0, unit: 'deg' },
  strain_gauge: { warning: 150.0, critical: 300.0, unit: 'µε' },
  pore_pressure: { warning: 15.0, critical: 30.0, unit: '%' }
};

for (const item of items) {
  const sensor = item.json;
  const readings = Array.isArray(sensor.readings) ? sensor.readings : [];

  if (readings.length < 2) {
    evaluatedItems.push({
      json: {
        flagged: false,
        status: "INSUFFICIENT_HISTORY",
        sensor_id: sensor.sensor_id || "UNKNOWN",
        notes: "Requires at least 2 historical steps to calculate rate of change."
      }
    });
    continue;
  }

  const currentValue = readings[readings.length - 1];
  const historicalBaseline = readings.slice(0, -1);
  const avgBaseline = historicalBaseline.reduce((acc, val) => acc + val, 0) / historicalBaseline.length;

  let delta = 0;
  let unit = '';
  let warningLimit = 0;
  let criticalLimit = 0;

  switch (sensor.sensor_type) {
    case 'inclinometer_tilt': {
      delta = Math.abs(currentValue - avgBaseline);
      const limits = THRESHOLDS.inclinometer_tilt;
      warningLimit = limits.warning;
      criticalLimit = limits.critical;
      unit = limits.unit;
      break;
    }
    case 'strain_gauge': {
      delta = Math.abs(currentValue - avgBaseline);
      const limits = THRESHOLDS.strain_gauge;
      warningLimit = limits.warning;
      criticalLimit = limits.critical;
      unit = limits.unit;
      break;
    }
    case 'pore_pressure': {
      delta = avgBaseline !== 0 ? ((currentValue - avgBaseline) / Math.abs(avgBaseline)) * 100 : 0;
      const limits = THRESHOLDS.pore_pressure;
      warningLimit = limits.warning;
      criticalLimit = limits.critical;
      unit = limits.unit;
      break;
    }
    default:
      continue;
  }

  const isAnomaly = delta >= warningLimit;
  const severity = delta >= criticalLimit ? 'CRITICAL' : (isAnomaly ? 'WARNING' : 'NOMINAL');
  const limitBreached = delta >= criticalLimit ? criticalLimit : warningLimit;

  evaluatedItems.push({
    json: {
      flagged: isAnomaly,
      severity: severity,
      sensor_id: sensor.sensor_id,
      sensor_type: sensor.sensor_type,
      location: sensor.location || {},
      current_value: Number(currentValue.toFixed(2)),
      baseline_average: Number(avgBaseline.toFixed(2)),
      observed_delta: Number(delta.toFixed(2)),
      exceeded_threshold: limitBreached,
      measurement_unit: unit,
      timestamp: new Date().toISOString(),
      action_required: isAnomaly ? "Dispatch Engineering Inspection Team" : "Routine Logging Only"
    }
  });
}

return evaluatedItems;

