// Processes and formats nominal (healthy) sensors for audit logs and SHM archiving
const items = $input.all();

return items.map(item => ({
  json: {
    audit_status: "HEALTHY_WITHIN_LIMITS",
    sensor_id: item.json.sensor_id,
    sensor_type: item.json.sensor_type,
    section: item.json.location?.section || "N/A",
    observed_delta: `${item.json.observed_delta} ${item.json.measurement_unit}`,
    baseline_average: `${item.json.baseline_average} ${item.json.measurement_unit}`,
    logged_at: item.json.timestamp || new Date().toISOString(),
    action_taken: "Archived telemetry log - No ticket required."
  }
}));
